===== runtime wasm emitter (src/lib.rs, UNROLLED kernel — kind constant-folded at codegen) =====
fn emit_kernel_unrolled(s, l) {
  s.i64_const(0).local_set(l.best); s.f64_const(f64c(-1.0)).local_set(l.best_v);
  for a in 0..N_ACTIONS {                 // 6 actions, fully unrolled
    s.f64_const(f64c(1.0)).local_set(l.prod);
    for c in 0..N_CONSID {                // 4 considerations, unrolled
      let xc = xc_local(l, c); let kind = (a + c) % 3;   // CONSTANT at codegen
      match kind {
        0 => { s.local_get(l.prod).local_get(xc).local_get(xc).f64_mul().f64_mul(); }   // prod *= x*x
        1 => { s.local_get(l.prod).local_get(xc).f64_mul(); }                            // prod *= x
        _ => { s.local_get(l.prod).f64_const(f64c(1.0)).local_get(xc).f64_sub().f64_mul(); } // prod *= 1-x
      }
      s.local_set(l.prod);
    }
    // momentum: prod = (a==last)? prod*1.25 : prod   (a constant, last runtime -> select)
    s.local_get(l.prod).f64_const(f64c(1.25)).f64_mul(); s.local_get(l.prod);
    s.i64_const(a).local_get(l.last).i64_eq(); s.select(); s.local_set(l.prod);
    // argmax (branchless)
    s.local_get(l.best_v).local_get(l.prod).f64_lt().local_set(l.cmp);
    s.i64_const(a).local_get(l.best).local_get(l.cmp).select().local_set(l.best);
    s.local_get(l.prod).local_get(l.best_v).local_get(l.cmp).select().local_set(l.best_v);
  }
}
